// DryRun checks text as Import does, adding nothing to c, and returns the
// titles of the items Import would add, in order.
func DryRun(c *Catalog, text string) ([]string, error) {
	items, err := check(text, c)
	if err != nil {
		return nil, err
	}
	var titles []string
	for _, it := range items {
		titles = append(titles, it.Title)
	}
	return titles, nil
}
